    }

    public function testBackedEnums()
    {
        $this->assertSame('2', (string) Js::from(IntBackedEnum::TWO));
        $this->assertSame("'Hello world'", (string) Js::from(StringBackedEnum::HELLO_WORLD));
    }
}

